function generateQR(){const e=document.getElementById("qr-input").value.trim(),t=document.getElementById("qr-result");if(!e){t.innerHTML='<p style="color:var(--text-muted);">'+i18n.t("tools_qr.qr_enter_text")+"</p>";return}const r=`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(e)}`;t.innerHTML=`<img src="${r}" alt="QR Code" onerror="this.onerror=null;this.parentElement.innerHTML='<p style=color:#ef4444;>' + i18n.t('common.error_qr') + '</p>'" style="max-width:200px; border:1px solid var(--border); border-radius:var(--radius-sm);"><br><a href="${r}" download="qrcode.png" target="_blank" rel="noopener" style="display:inline-block; margin-top:.8rem; color:var(--primary); font-weight:600;">${i18n.t("tools_qr.download_link")}</a>`,t.innerHTML+='<div style="margin-top:.5rem; font-size:.8rem; color:var(--text-muted);">'+i18n.t("tools_qr.api_notice")+"</div>"}function downloadResult(){const e=document.getElementById("qr-input").value.trim();if(!e)return showToast(i18n.t("common.no_qr_text"));downloadFile(e,"qr-content.txt")}function clearAll(){document.getElementById("qr-input").value="",document.getElementById("qr-result").innerHTML='<p style="color:var(--text-muted);">'+i18n.t("tools_qr.qr_placeholder")+"</p>"}
